use hec_native_ic::{fp::Fp,jac::{Curve,Div},poly::Poly};
// Caller separately checks valid anchor and that support points lie on the curve.
pub fn roots(c:&Curve,a:&Div,t:u64,points:&[(u64,u64)])->bool{if c.g!=2||c.f.deg()!=5||c.f.lc()!=1||a.u.deg()!=2||a.u.lc()!=1||a.v.deg()>=2||t>=c.fp.p||points.len()!=3{return false}let vt=a.v.add(&a.u.scale(t,&c.fp),&c.fp);let mut seen=std::collections::BTreeSet::new();for &(x,y)in points{if x>=c.fp.p||y>=c.fp.p||!seen.insert(x)||a.u.eval(x,&c.fp)==0||vt.eval(x,&c.fp)!=y{return false}}true}
fn full(c:&Curve,a:&Div,t:u64,points:&[(u64,u64)])->bool{c.is_valid(a)&&roots(c,a,t,points)&&points.iter().all(|&(x,y)|c.fp.mul(y,y)==c.f.eval(x,&c.fp))}
fn control_exact(c:&Curve,a:&Div,t:u64,points:&[(u64,u64)])->bool{let vt=a.v.add(&a.u.scale(t,&c.fp),&c.fp);let lhs=c.f.sub(&vt.mul(&vt,&c.fp),&c.fp);let mut rhs=a.u;for &(x,_)in points{rhs=rhs.mul(&Poly::x_minus(x,&c.fp),&c.fp);}lhs==rhs}
pub fn controls(){let fp=Fp::new(101);let mut f=Poly::one();for x in 0..5{f=f.mul(&Poly::x_minus(x,&fp),&fp);}f=f.add(&Poly::one(),&fp);let c=Curve{fp,f,g:2};let a=Div{u:Poly::from_coeffs(&[0,100,1]),v:Poly::one()};let good=[(2,1),(3,1),(4,1)];assert!(full(&c,&a,0,&good));assert!(control_exact(&c,&a,0,&good));let overlap=[(0,1),(2,1),(3,1)];assert!(overlap.iter().all(|&(x,y)|c.f.eval(x,&fp)==fp.mul(y,y)));assert!(!full(&c,&a,0,&overlap));assert!(!control_exact(&c,&a,0,&overlap));assert!(!full(&c,&a,0,&[(2,1),(2,1),(3,1)]));assert!(!full(&c,&a,0,&[(2,1),(3,1),(5,1)]));let bad=Div{u:a.u,v:Poly::constant(2)};assert!(!full(&c,&bad,0,&good));eprintln!("polynomial_lemma_positive=1 negatives=4 overlap_counterexample_to_omitted_guard=true");}

pub fn exact(c:&Curve,a:&Div,t:u64,points:&[(u64,u64)])->bool{if points.len()!=3||a.u.deg()!=2||t>=c.fp.p{return false}let vt=a.v.add(&a.u.scale(t,&c.fp),&c.fp);let lhs=c.f.sub(&vt.mul(&vt,&c.fp),&c.fp);let mut rhs=a.u;for &(x,y)in points{if x>=c.fp.p||y>=c.fp.p||vt.eval(x,&c.fp)!=y{return false}rhs=rhs.mul(&Poly::x_minus(x,&c.fp),&c.fp);}lhs==rhs}
pub fn repeated_control(){let fp=Fp::new(101);let u=Poly::from_coeffs(&[0,100,1]);let h=Poly::x_minus(2,&fp).mul(&Poly::x_minus(2,&fp),&fp).mul(&Poly::x_minus(3,&fp),&fp);let f=u.mul(&h,&fp).add(&Poly::one(),&fp);let c=Curve{fp,f,g:2};let a=Div{u,v:Poly::one()};let pts=[(2,1),(2,1),(3,1)];assert!(c.is_valid(&a));assert!(!roots(&c,&a,0,&pts));assert!(exact(&c,&a,0,&pts));eprintln!("repeated_root_exact_positive=true");}
